$stmt=$pdo->prepare("SELECT p.*,fd.num_fiche,fd.mode_paiement,c.reference,c.document_id,c.objet,c.montant_ht,c.taux_acompte,c.montant_acompte,c.retenue_garantie_taux,c.date_debut,c.date_fin,c.delai_jours,ch.code chantier_code,ch.titre chantier_titre,COALESCE(NULLIF(s.nom_commercial,''),NULLIF(s.raison_sociale,''),CONCAT(s.person_first_name,' ',s.person_last_name)) fournisseur_nom,s.contact_nom,s.telephone,s.email,s.adresse,s.ncc FROM contrat_sous_traitance_paiement p JOIN contrat_sous_traitance c ON c.id=p.contrat_id JOIN chantier_banamur ch ON ch.id=c.chantier_id JOIN fournisseur_banamur s ON s.id_fournisseur=c.fournisseur_id LEFT JOIN fiche_decaissement fd ON fd.id_fiche=p.fiche_id WHERE p.id=?");$stmt->execute([$paymentId]);$p=$stmt->fetch(PDO::FETCH_ASSOC);if(!$p){http_response_code(404);exit('PV introuvable');}
$stmt=$pdo->prepare("SELECT cl.montant_contractuel,cl.poids,ld.designation,ld.quantite,u.symbole unite FROM contrat_sous_traitance_ligne cl JOIN ligne_devis_banamur ld ON ld.id=cl.ligne_devis_id LEFT JOIN unites_mesure u ON u.id=ld.unite_id WHERE cl.contrat_id=? ORDER BY cl.id");$stmt->execute([(int)$p['contrat_id']]);$lines=$stmt->fetchAll(PDO::FETCH_ASSOC);
