$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$date=static fn($v)=>$v?date('d/m/Y',strtotime((string)$v)):'Non renseignée';$money=static fn($v)=>number_format((float)$v,0,',',' ').' FCFA';$labels=['acompte'=>'Acompte pour exécution','avancement'=>'Paiement sur avancement','solde'=>'Solde contractuel'];$decisionLabels=['sans_reserve'=>'Réception sans réserve','avec_reserves'=>'Réception avec réserves','refuse'=>'Réception refusée'];$supplierSignerName=trim((string)($p['contact_nom']??''))?:trim((string)$p['fournisseur_nom']);$supplierSignerRole='Représentant du sous-traitant';
$taskSource=$recordedWorks?:$lines;$tasks='';foreach($taskSource as $i=>$line){$isReserve=!empty($line['reserve']);$hasSeparateReserve=array_key_exists('reserve_description',$line);$workObservation=trim((string)($hasSeparateReserve?($line['observation']??''):($isReserve?'':($line['observation']??''))));$reserveDescription=trim((string)($line['reserve_description']??($isReserve?($line['observation']??''):'')));$details=($workObservation!==''?'<br><span style="color:#555555"><b>TRAVAUX RÉALISÉS :</b> '.$e($workObservation).'</span>':'').($isReserve&&$reserveDescription!==''?'<br><span style="color:#8a6500"><b>RÉSERVE :</b> '.$e($reserveDescription).'</span>':'');$tasks.='<tr nobr="true"><td width="7%" align="center">'.($i+1).'</td><td width="43%"><b>'.$e($line['designation']).'</b>'.$details.'</td><td width="13%" align="center">'.$e($line['quantite'].' '.($line['unite']?:'')).'</td><td width="17%" align="right">'.$money($line['montant']??$line['montant_contractuel']).'</td><td width="10%" align="center">'.number_format((float)$line['poids'],2,',',' ').' %</td><td width="10%" align="center">'.number_format((float)($line['avancement']??$p['avancement_cumule']),2,',',' ').' %</td></tr>';}$remaining=max(0,(float)$p['montant_ht']-$paidToDate);
