// TCPDF ne prend pas réellement en charge border-radius dans son moteur HTML.
// Les cartes sont donc extraites puis dessinées nativement avec RoundedRect.
$renderRoundedCards=static function(TCPDF $document,string $content):void{
    $stylesheet='';if(preg_match('~<style>.*?</style>~s',$content,$styleMatch)){$stylesheet=$styleMatch[0];$content=str_replace($stylesheet,'',$content);}
    $offset=0;
    while(preg_match('~<div class="card"(?:\s+style="([^"]*)")?>(.*?)</div>~s',$content,$match,PREG_OFFSET_CAPTURE,$offset)){
        $start=$match[0][1];$before=substr($content,$offset,$start-$offset);
        if($before!=='')$document->writeHTML($stylesheet.$before,true,false,true,false,'');
        $inner=$match[2][0];$plain=trim(preg_replace('/\s+/u',' ',strip_tags(str_replace(['<br>','<br/>','<br />'],"\n",$inner))));
        $height=max(18.0,$document->getStringHeight(166,$plain)+9.0);
        if(str_contains($inner,'OBJET DU CONTRAT'))$height=max($height,42.0);
        elseif(str_contains($inner,'Facture FNE'))$height=max($height,24.0);
        elseif(str_contains($inner,'OBSERVATIONS / RÉSERVES'))$height=max($height,32.0);
        elseif(str_contains($inner,'Décision enregistrée'))$height=max($height,28.0);
        if($document->GetY()+$height>$document->getPageHeight()-28)$document->AddPage();
        $x=15.0;$y=$document->GetY();$width=$document->getPageWidth()-30.0;
        $document->SetDrawColor(120,120,120);$document->SetLineWidth(.25);$document->SetFillColor(255,249,219);
        $document->RoundedRect($x,$y,$width,$height,3.5,'1111','DF');
        $document->SetXY($x+4.5,$y+4.0);$document->writeHTMLCell($width-9,$height-7,'','',$stylesheet.$inner,0,0,false,true,'L',true);
        $document->SetY($y+$height+5.0);$offset=$start+strlen($match[0][0]);
    }
    $tail=substr($content,$offset);if($tail!=='')$document->writeHTML($stylesheet.$tail,true,false,true,false,'');
};
$renderRoundedCards($pdf,$html);while(ob_get_level()>0)ob_end_clean();$pdf->Output('PV_'.$p['reference'].'_'.$p['num_fiche'].'.pdf','I');exit;
